use std::rc::Rc;
use std::thread;

fn main() {
    let nums = Rc::new(vec![1, 2, 3]);
    let n1 = Rc::clone(&nums);
    let n2 = Rc::clone(&nums);
    let h1 = thread::spawn(move || {
        println!("len in thread 1: {}", n1.len());
    });
    let h2 = thread::spawn(move || {
        println!("len in thread 2: {}", n2.len());
    });
    println!("len in main: {}", nums.len());
    h1.join().unwrap();
    h2.join().unwrap();
}

